<script setup>
import { computed,ref } from 'vue';
import { Plus,Search,Trash2,Pencil,Check,Box,Copy,FolderOpen,Save,RefreshCw,Download,Upload,Share2 } from 'lucide-vue-next';
import ComponentPreview from './ComponentPreview.vue';
const props=defineProps({studio:Object});const s=props.studio,query=ref(''),creating=ref(false),renaming=ref(null),name=ref('');
const filtered=computed(()=>s.libraryComponents.filter(c=>c.name.toLocaleLowerCase().includes(query.value.toLocaleLowerCase())));
function create(){s.createComponent();creating.value=false;query.value='';}
function rename(c){s.renameComponent(c,name.value);renaming.value=null;}
</script>
<template><section class="components-library"><div class="library-heading"><div><h3>Bibliothèque</h3><p>{{s.libraryComponents.length}} composant{{s.libraryComponents.length>1?'s':''}} {{s.libraryScope==='shared'?'dans la bibliothèque partagée':'dans ce projet'}}</p></div><Box :size="22"/></div><div class="library-scope"><button class="btn" :class="{active:s.libraryScope==='project'}" :aria-pressed="s.libraryScope==='project'" @click="s.libraryScope='project'">Projet</button><button class="btn" :class="{active:s.libraryScope==='shared'}" :aria-pressed="s.libraryScope==='shared'" @click="s.libraryScope='shared'">Partagée</button></div><section v-if="s.libraryScope==='shared'" class="shared-library-tools"><strong>{{s.sharedFileName||'Aucun fichier lié'}}{{s.sharedDirty?' •':''}}</strong><p class="field-help">Ouvre le même fichier dans chaque navigateur. Enregistre pour partager ; Actualiser relit les changements. Les composants présents sont conservés à l’ouverture.</p><div class="library-file-actions"><button v-if="s.sharedFileSupported" class="btn" :disabled="s.sharedBusy" @click="s.openSharedLibrary"><FolderOpen :size="14"/>Ouvrir</button><button v-if="s.sharedFileSupported" class="btn" :disabled="s.sharedBusy" @click="s.saveSharedLibrary()"><Save :size="14"/>Enregistrer</button><button v-if="s.sharedFileName" class="btn" :disabled="s.sharedBusy" @click="s.refreshSharedLibrary()"><RefreshCw :size="14"/>Actualiser</button><button v-if="s.sharedFileSupported&&s.sharedFileName" class="btn" :disabled="s.sharedBusy" @click="s.saveSharedLibrary(true)">Enregistrer sous</button></div><p v-if="s.sharedDirty" class="field-help">Modifications à enregistrer dans le fichier partagé.</p><p v-if="s.sharedError" class="library-error" role="status">{{s.sharedError}}</p><p v-if="!s.sharedFileSupported" class="field-help">Ce navigateur utilise l’import/export JSON pour partager la bibliothèque.</p></section><div class="library-file-actions"><button class="btn" @click="s.exportComponents"><Download :size="14"/>Exporter</button><label class="btn"><Upload :size="14"/>Importer<input type="file" accept="application/json,.json" :disabled="s.libraryScope==='shared'&&s.sharedBusy" hidden @change="s.importComponents"></label></div><button class="btn primary full" :disabled="!s.selectedKeys.length||(s.libraryScope==='shared'&&s.sharedBusy)" @click="creating=!creating"><Plus :size="16"/>Créer avec la sélection</button><p class="field-help">{{s.selectedKeys.length?s.selectedKeys.length+' objet(s) à enregistrer':'Sélectionne des objets dans la diapo pour créer un composant.'}}</p><form v-if="creating" class="component-create" @submit.prevent="create"><label>Nom<input v-model="s.componentName" maxlength="60" aria-label="Nom du composant" required></label><div><button class="btn" type="button" @click="creating=false">Annuler</button><button class="btn primary" :disabled="!s.componentName.trim()||!s.selectedKeys.length">Créer</button></div></form><label class="library-search"><Search :size="16"/><input v-model="query" placeholder="Rechercher un composant…" aria-label="Rechercher un composant"></label><div v-if="!s.libraryComponents.length" class="library-empty"><Box :size="32"/><strong>Ta bibliothèque commence ici</strong><p>Enregistre un titre, une carte ou un groupe d’objets pour le réutiliser dans tes diapos.</p></div><p v-else-if="!filtered.length" class="field-help">Aucun composant ne correspond à cette recherche.</p><article v-for="c in filtered" :key="c.id" class="component-card"><button class="component-insert-preview" :aria-label="'Insérer '+c.name" @click="s.useComponent(c)"><ComponentPreview :component="c" :theme="s.theme"/><span><Plus :size="16"/>Insérer</span></button><div class="component-card-info"><form v-if="renaming===c.id" @submit.prevent="rename(c)"><input v-model="name" :disabled="s.libraryScope==='shared'&&s.sharedBusy" aria-label="Nouveau nom du composant" maxlength="60" required><button class="icon-btn" aria-label="Valider le nom"><Check :size="16"/></button></form><template v-else><div><strong>{{c.name}}</strong><small>{{c.items.length}} objet{{c.items.length>1?'s':''}}</small></div><button class="icon-btn" :aria-label="'Copier '+c.name" title="Copier vers une autre instance" @click="s.copyComponent(c)"><Copy :size="14"/></button><button v-if="s.libraryScope==='project'" class="icon-btn" :disabled="s.sharedBusy" :aria-label="'Partager '+c.name" title="Ajouter à la bibliothèque partagée" @click="s.shareComponent(c)"><Share2 :size="14"/></button><button class="icon-btn" :disabled="s.libraryScope==='shared'&&s.sharedBusy" :aria-label="'Renommer '+c.name" @click="renaming=c.id;name=c.name"><Pencil :size="14"/></button><button class="icon-btn" :disabled="s.libraryScope==='shared'&&s.sharedBusy" :aria-label="'Supprimer '+c.name" @click="s.deleteComponent(c.id)"><Trash2 :size="14"/></button></template></div></article><p v-if="s.libraryComponents.length" class="field-help">Chaque insertion crée une copie personnalisable. Double-clique sur un membre pour modifier son texte.</p></section></template>
